#!/usr/bin/env bash
# Publish the website and the browser build to GitHub Pages.
#
#   tool/deploy_pages.sh              # build the app, assemble, push to gh-pages
#   SKIP_APP=1 tool/deploy_pages.sh   # pages only: keeps the app already deployed
#   REGEN=1 tool/deploy_pages.sh      # regenerate the pages from the repo first
#   REUSE_BUILD=1 tool/deploy_pages.sh  # deploy the existing build/web
#
# Pages serves the `gh-pages` branch root, so the site is `docs/` (generated by
# tool/gen_site.py) plus `app/` (the Flutter web build). A branch, not `docs/` on
# main, because the 40 MB browser build must not sit in the history of a repo that
# people clone; the branch is force-pushed, so it holds exactly one commit.
#
# The project site is always served under /Puzzlestack/, so the app is built with
# that base href and every link in the pages is relative.
#
# A force-push replaces the whole branch, so this script refuses to publish a tree
# that would break the site: every page links to `app/`, and a `SKIP_APP` run
# carries over the build that is already deployed rather than dropping it.
set -euo pipefail

ROOT=$(cd "$(dirname "$0")/.." && pwd)
BRANCH=${BRANCH:-gh-pages}
BASE_HREF=${BASE_HREF:-/Puzzlestack/app/}
ORIGIN_URL=${ORIGIN_URL:-$(git -C "$ROOT" remote get-url origin)}
OUT=$(mktemp -d "${TMPDIR:-/tmp}/puzzlestack-pages.XXXXXX")
CARRY=$(mktemp -d "${TMPDIR:-/tmp}/puzzlestack-app.XXXXXX")
trap 'rm -rf "$OUT" "$CARRY"' EXIT

die() { echo "refusing to deploy: $*" >&2; exit 1; }

echo "== pages"
if [ -n "${REGEN:-}" ]; then
  (cd "$ROOT" && dart run tool/site_export.dart && python3 tool/gen_site.py)
fi
# Only the site ships. `docs/` is also where the repo's design and audit notes
# live (markdown, screenshots); they stay in the repo and out of the published
# tree, which keeps the site to pages, stylesheet, fonts and the app.
rsync -a --prune-empty-dirs \
  --include '*/' --include '*.html' --include 'site.css' \
  --include 'sitemap.xml' --include 'robots.txt' \
  --include 'fonts/' --include 'fonts/**' \
  --exclude '*' \
  "$ROOT/docs/" "$OUT/"
[ -f "$OUT/index.html" ] || die "docs/index.html is missing"
[ -f "$OUT/games/index.html" ] || die "docs/games/index.html is missing"
[ -f "$OUT/sitemap.xml" ] || die "docs/sitemap.xml is missing"

echo "== app"
if [ -z "${SKIP_APP:-}" ]; then
  if [ -n "${REUSE_BUILD:-}" ] && [ -f "$ROOT/build/web/index.html" ]; then
    echo "   reusing build/web"
  else
    (cd "$ROOT" && flutter build web --release --base-href "$BASE_HREF")
  fi
  # Debug symbols the loader never fetches.
  find "$ROOT/build/web" -name '*.symbols' -delete
  rsync -a --delete "$ROOT/build/web/" "$OUT/app/"
else
  # Pages-only run: carry the deployed build forward instead of deleting it.
  if git ls-remote --exit-code --heads "$ORIGIN_URL" "$BRANCH" >/dev/null 2>&1; then
    git init -q "$CARRY"
    git -C "$CARRY" remote add origin "$ORIGIN_URL"
    git -C "$CARRY" fetch -q --depth 1 origin "$BRANCH"
    if git -C "$CARRY" checkout -q FETCH_HEAD -- app 2>/dev/null; then
      rsync -a "$CARRY/app/" "$OUT/app/"
      echo "   carried $(du -sh "$OUT/app" | cut -f1) of the deployed app forward"
    fi
  fi
fi
# The 230 game pages link into app/. A tree without it turns every Play button
# into a 404, so an app-less deploy is an error, not a smaller site.
[ -f "$OUT/app/index.html" ] || die "no app/ in the tree (use a full run, not SKIP_APP, the first time)"

cat > "$OUT/.nojekyll" <<<''

echo "== size"
du -sh "$OUT"
du -sh "$OUT/app" 2>/dev/null || true

echo "== commit"
(
  cd "$OUT"
  git init -q -b "$BRANCH"
  git add -A
  git -c user.name="$(git -C "$ROOT" config user.name)" \
      -c user.email="$(git -C "$ROOT" config user.email)" \
      commit -q -m "site: $(date -u +%Y-%m-%dT%H:%MZ) from $(git -C "$ROOT" rev-parse --short HEAD)"
  git remote add origin "$ORIGIN_URL"
  git push -q --force origin "$BRANCH"
)

echo "== done: https://cyoren.github.io/Puzzlestack/ (Pages must serve $BRANCH)"
